import {renderDiagram,renderModel,enable3D,models} from './visual.js?v=20261023-physicscomplete01';
const label=(x,y,t,size=13)=>`<text x="${x}" y="${y}" fill="#f8f6f2" font-size="${size}" text-anchor="middle" font-family="sans-serif">${t}</text>`;
export function showSolution(c=12,v=250){const h=Math.max(20,Math.min(155,v/1500*155));renderDiagram('Volume and solute mass',`${c} g/dm³ · ${v} cm³`,`<svg class="lab-svg" viewBox="0 0 440 285" role="img" aria-label="Schematic solution vessel at${v} cubic centimetres and${c} grams per cubic decimetre, not to scale."><path d="M145 45V230H295V45" fill="none" stroke="#b7c8d6" stroke-width="3"/><rect x="147" y="${228-h}" width="146" height="${h}" fill="#b7c8d6" opacity=".5"/>${label(220,30,'Total solution volume',16)}${label(220,263,'Symbolic fill level · calculate before revealing mass',10)}</svg>`,'CALCULATION MODEL · NOT LAB APPARATUS');}
export function showMole(symbol='CO2'){const m=symbol==='H2O'?models.water:symbol==='CO2'?models.carbon:{name:'Carbon atom',formula:'C',atoms:[['C',0,0,0]],bonds:[]};enable3D();renderModel({...m,zoom:12,kicker:'ONE REPRESENTATIVE PARTICLE · NOT ONE MOLE',aria:'One representative '+(symbol==='C'?'carbon atom':symbol==='H2O'?'water molecule':'carbon dioxide molecule')+'. One mole contains6.02 times10 to the power23 such specified particles.'});}
export function showRatio(t=null){renderDiagram('Mass → mol → mol → mass',t?.equation||'Use balanced coefficients',`<div class="diagram-card"><span class="eyebrow">THREE-STEP ROUTE</span><p>Given mass ÷ given Mᵣ</p><p>× required coefficient ÷ given coefficient</p><p>× required Mᵣ</p><p>${t?t.excess+' is supplied in excess.':'Enough of the other reactants is assumed.'}</p></div>`,'CALCULATED COMPLETE REACTION · NOT ACTUAL YIELD');}
export function showAmount(kind){if(kind==='concentration')showSolution();else if(kind==='moles')showMole();else showRatio();}
